      if (currentV < 17) {
        // Step 1: Remove duplicate enrollments — keep oldest per (subscriber_id, course_id)
        // Uses self-join DELETE: safe in MySQL, keeps the row with earliest enrolled_at
        // Tie-break on id (lexicographic) so exactly one row survives per pair
        const [dedupResult] = await pool.query(`
          DELETE e1 FROM enrollments e1
          INNER JOIN enrollments e2
            ON e1.subscriber_id = e2.subscriber_id
            AND e1.course_id = e2.course_id
            AND e1.course_id IS NOT NULL
            AND (e1.enrolled_at > e2.enrolled_at
              OR (e1.enrolled_at = e2.enrolled_at AND e1.id > e2.id))
        `).catch(e => { logger.warn('[schema] v17 dedup error:', e.message); return [{ affectedRows: 0 }]; });
        const removed = dedupResult?.affectedRows ?? 0;
        if (removed > 0) logger.info(`[schema] v17: removed ${removed} duplicate enrollment rows`);

        // Step 2: Add UNIQUE KEY — prevents future duplicate enrollments
        // ON DUPLICATE KEY UPDATE in INSERT statements will now work correctly
        await pool.query(
          'ALTER TABLE enrollments ADD UNIQUE KEY uniq_enroll_sub_course (subscriber_id, course_id)'
        ).catch(e => logger.warn('[schema] v17 unique key (may already exist):', e.message));

        await pool.query(
          "INSERT INTO site_config (`key`, `value`) VALUES ('schema_version', '17') ON DUPLICATE KEY UPDATE `value`='17'"
        ).catch(migCatch);
        logger.info('[schema] v17: enrollment dedup + unique constraint ready');
      }

