        const [leadBackfill] = await pool.query(`
          UPDATE leads l
          INNER JOIN subscribers s ON s.lead_id = l.id
          SET l.status = 'converted'
          WHERE LOWER(l.status) NOT IN ('converted', 'lost')
        `).catch(e => { logger.warn('[schema] v18 lead backfill error:', e.message); return [{ affectedRows: 0 }]; });
        const converted = leadBackfill?.affectedRows ?? 0;
        if (converted > 0) logger.info(`[schema] v18: backfilled ${converted} leads to converted`);

